css:
#loader-c-6 {
  --c: #000;
  width: fit-content;
  font-weight: bold;
  font-family: monospace;
  font-size: 30px;
  color: #0000;
  overflow: hidden;
  text-shadow: 0 0 var(--c), 11ch 0 var(--c);
  animation: l6 2s infinite linear;
}
#loader-c-6:before {
  content: "Loading...";
}
@keyframes l6 {
  to {
    text-shadow: -11ch 0 var(--c), 0ch 0 var(--c);
  }
}
